/** Events */
export const events = {
	attentionNavigate: makeEvent<AttentionNavigate>("attention-navigate"),
	backendPulse: makeEvent<BackendPulse>("backend-pulse"),
	fleetClick: makeEvent<FleetClick>("fleet-click"),
	fleetRosterChanged: makeEvent<FleetRosterChanged>("fleet-roster-changed"),
	fleetShown: makeEvent<FleetShown>("fleet-shown"),
	loopUpdated: makeEvent<LoopUpdated>("loop-updated"),
	notificationAdded: makeEvent<NotificationAdded>("notification-added"),
	prefsChanged: makeEvent<PrefsChanged>("prefs-changed"),
	sessionUpdated: makeEvent<SessionUpdated>("session-updated"),
};

/* Types */
/**  Whether the account guardrail preflight was read (K3). */
export type AccountCheck = "checked" | "unknown";

export type ActionCapabilities = {
	prompt: ActionCapability,
	question: ActionCapability,
	approval: ActionCapability,
	plan: ActionCapability,
	queue: ActionCapability,
};

export type ActionCapability = { channel: "pty" } | { channel: "held-hook" } | { channel: "server" } | { channel: "transcript" } | { channel: "unavailable"; reason: string };

export type ActionRequest = {
	runId: number,
	requestId: string,
	action: SessionAction,
};

export type ActionResult = { kind: "prompt"; receipt: Delivered } | { kind: "reply"; receipt: ReplyReceipt };

export type Activity = 
/**  No event yet, or the agent has no event channel (Grok, a shell). */
"unknown" | 
/**  A turn is in progress. */
"working" | 
/**  The agent waits for permission to act. */
"awaiting-approval" | 
/**  The agent asked a question, or ended its turn with one. */
"needs-answer" | 
/**  The turn ended and the agent waits for the next prompt. */
"ready" | 
/**  The turn ended in an error. */
"failed";

/**
 *  What Chorus can say about a session's address: exactly three states. A collision is a cause
 *  on `changed`, given only when another live session holds the requested name.
 */
export type AddressState = { kind: "verified"; address: string } | { kind: "changed"; requested: string; current: string; collision: boolean } | { kind: "unknown"; reason: string };

export type AgentInfo = {
	kind: AgentKind,
	displayName: string,
	/**
	 *  Empty when the agent has no setting for it; the form then leaves the control out and says
	 *  why.
	 */
	efforts: EffortChoice[],
	defaultEffort: Effort | null,
	permissions: PermissionChoice[],
	defaultPermission: Permission | null,
	takesModel: boolean,
	/**  Options go into the configuration of a server Chorus starts (opencode), not argv. */
	optionsInConfig: boolean,
	/**  The agent reports turns to Chorus. Without it, a running session is only "Running" (D47). */
	hasEventChannel: boolean,
	/**  An effort applies only with a model named beside it (opencode, LESSONS L5). */
	effortNeedsModel: boolean,
	resume: ResumeKind,
	/**  The CLI version the options were checked against. */
	verifiedVersion: string | null,
	/**  None until the first detection finishes. */
	detection: Detection | null,
};

export type AgentKind = "shell" | "claude" | "codex" | "opencode" | "grok" | "gemini" | "aider";

/**  Whether an agent can run on the provider; `reason` says why not. */
export type AgentRoute = {
	agent: AgentKind,
	reason: string | null,
};

export type AppInfo = {
	productName: string,
	version: string,
	identifier: string,
	flavor: Flavor,
	/**  The live data directory. Shown in the window so it's always clear which data is in use. */
	dataDir: string,
	/**  The user's home folder, so paths can be shown as ~/... */
	homeDir: string | null,
	tauriVersion: string,
};

export type ApprovalDecision = "allow" | "deny";

export type AskEntry = {
	id: number,
	kind: string,
	subject: string,
	answer: string | null,
	details: ReplyDetails | null,
	replyAttempted: boolean,
	replyAction: SessionAction | null,
};

/**  In urgency order, most urgent first. */
export type Attention = 
/**  The agent waits for permission to act. */
"approval" | 
/**  The agent asked a question. */
"input" | 
/**  The last turn failed, the process exited with an error, or it couldn't start. */
"failed" | "working" | 
/**  The turn ended; the agent waits for the next prompt. */
"ready" | 
/**
 *  Running, with no event channel to say more (a shell, Grok, or an agent before its first
 *  event). Never shown as working (ARCHITECTURE §6).
 */
"running" | 
/**  Exited cleanly, or closed. */
"done";

